(() => {
  'use strict';

  const LOGO_SRC = 'data:image/png;base64,';

  const $ = (q, root=document) => root.querySelector(q);
  const $$ = (q, root=document) => [...root.querySelectorAll(q)];
  const app = $('#app');

  const K = {
    clients:'sigraf_clients_v2', services:'sigraf_services_v2', sales:'sigraf_sales_v2', cash:'sigraf_cash_v2',
    settings:'sigraf_settings_v2'
  };

  const todayISO = () => new Date().toISOString().slice(0,10);
  const uid = () => Date.now().toString(36)+Math.random().toString(36).slice(2,8);
  const money = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  const esc = v => String(v??'').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const norm = v => String(v??'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const dateBR = v => v ? new Date(v+'T12:00:00').toLocaleDateString('pt-BR') : '—';
  const read = (k,fallback) => { try { const v=localStorage.getItem(k); return v?JSON.parse(v):fallback; } catch { return fallback; } };
  const write = (k,v) => localStorage.setItem(k,JSON.stringify(v));
  const storageToState = Object.fromEntries(Object.entries(K).map(([name, key]) => [key, name]));
  let databaseOnline = false;
  let databaseKeys = new Set();
  async function api(path, options={}){
    const res = await fetch(path, {
      ...options,
      headers: {'Content-Type':'application/json', ...(options.headers||{})}
    });
    if(!res.ok) throw new Error('Falha na API');
    return res.json();
  }
  async function checkSession(){
    try {
      const session = await api('/api/session');
      return !!session.logged;
    } catch {
      return false;
    }
  }
  async function loadDatabase(){
    try {
      const data = await api('/api/state');
      databaseOnline = true;
      databaseKeys = new Set(Array.isArray(data._keys) ? data._keys : []);
      for(const key of ['clients','services','sales','cash']){
        if(databaseKeys.has(key) && Array.isArray(data[key])) write(K[key], data[key]);
      }
      if(databaseKeys.has('settings') && data.settings) write(K.settings, data.settings);
      return true;
    } catch {
      databaseOnline = false;
      databaseKeys = new Set();
      return false;
    }
  }
  function saveDatabase(key, value){
    if(!databaseOnline) return;
    api('/api/state/'+key, {method:'PUT', body:JSON.stringify(value)}).catch(() => {
      databaseOnline = false;
      toast('Sem conexão com o banco. Dados salvos neste navegador.', 'error');
    });
  }
  function download(blob,name){ const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),500); }

  const demo = {
    clients:[
      {id:'c1',name:'Maria Aparecida',cpf:'123.456.789-00',address:'Rua das Flores, 120',reference:'Próximo à praça',cep:'84940-000',createdAt:todayISO()},
      {id:'c2',name:'Mercado Central',cpf:'12.345.678/0001-90',address:'Av. Brasil, 450',reference:'Em frente ao banco',cep:'84940-000',createdAt:todayISO()}
    ],
    services:[
      {id:'s1',clientId:'c1',description:'500 Cartões de Visita 4x4',qty:1,unitPrice:95,total:95,status:'Em produção',dueDate:todayISO(),paymentMethod:'PIX',createdAt:todayISO(),paid:true},
      {id:'s2',clientId:'c2',description:'Banner 90x120 cm',qty:2,unitPrice:75,total:150,status:'Pronto',dueDate:todayISO(),paymentMethod:'Cartão',createdAt:todayISO(),paid:true}
    ],
    sales:[{id:'v1',clientId:'c1',material:'Adesivo Vinil A3',qty:3,unitPrice:18,total:54,paymentMethod:'Dinheiro',createdAt:todayISO(),paid:true}],
    cash:[
      {id:'x1',date:todayISO(),type:'entrada',category:'Serviços',description:'500 Cartões de Visita 4x4',amount:95,paymentMethod:'PIX',source:'service',sourceId:'s1'},
      {id:'x2',date:todayISO(),type:'entrada',category:'Serviços',description:'Banner 90x120 cm',amount:150,paymentMethod:'Cartão',source:'service',sourceId:'s2'},
      {id:'x3',date:todayISO(),type:'entrada',category:'Vendas',description:'Adesivo Vinil A3',amount:54,paymentMethod:'Dinheiro',source:'sale',sourceId:'v1'},
      {id:'x4',date:todayISO(),type:'saida',category:'Materiais',description:'Compra papel couchê',amount:68,paymentMethod:'PIX',source:'manual'}
    ]
  };

  let state = {
    page:'dashboard', logged:false, sidebar:false,
    clients:[],services:[],sales:[],cash:[], settings:{businessName:'Sigraf Gráfica',adminName:'Administrador'}
  };

  const icons = {
    dashboard:'<path d="M3 3h7v7H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 14h7v7H3z"/>',
    printer:'<path d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6z"/>',
    wallet:'<path d="M20 7V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v10a2 2 0 0 1-2 2H5a3 3 0 0 1-3-3V6"/><path d="M16 13h4"/>',
    cart:'<circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M3 4h2l2.7 10.4a2 2 0 0 0 2 1.6h7.7a2 2 0 0 0 2-1.6L21 8H6"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><path d="M20 8v6M23 11h-6"/>',
    chart:'<path d="M3 3v18h18"/><path d="m7 16 4-5 4 3 5-7"/>',
    settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-4v-.09A1.7 1.7 0 0 0 9 19.36a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.63 15 1.7 1.7 0 0 0 3.09 14H3v-4h.09A1.7 1.7 0 0 0 4.64 9a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.63 1.7 1.7 0 0 0 10 3.09V3h4v.09A1.7 1.7 0 0 0 15 4.64a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.37 9 1.7 1.7 0 0 0 20.91 10H21v4h-.09A1.7 1.7 0 0 0 19.4 15z"/>',
    logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5M21 12H9"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>',
    edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4z"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2M19 6l-1 15H6L5 6M10 11v6M14 11v6"/>',
    save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><path d="M17 21v-8H7v8M7 3v5h8"/>',
    down:'<circle cx="12" cy="12" r="10"/><path d="m8 12 4 4 4-4M12 8v8"/>',
    up:'<circle cx="12" cy="12" r="10"/><path d="m8 12 4-4 4 4M12 16V8"/>',
    dollar:'<circle cx="12" cy="12" r="10"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8M12 6v12"/>',
    package:'<path d="m16.5 9.4-9-5.2M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><path d="M3.3 7 12 12l8.7-5M12 22V12"/>',
    clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
    download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5M12 15V3"/>',
    upload:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m17 8-5-5-5 5M12 3v12"/>',
    refresh:'<path d="M3 12a9 9 0 0 1 15-6l3 3M21 3v6h-6M21 12a9 9 0 0 1-15 6l-3-3M3 21v-6h6"/>',
    warning:'<path d="M10.3 2.9 1.8 17a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 2.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4M12 17h.01"/>',
    building:'<path d="M3 21h18M6 21V3h12v18M9 7h2M13 7h2M9 11h2M13 11h2M9 15h2M13 15h2"/>',
    eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',
    eyeoff:'<path d="m3 3 18 18M10.6 10.6A2 2 0 0 0 13.4 13.4M9.9 4.2A10 10 0 0 1 12 4c6.5 0 10 8 10 8a18 18 0 0 1-2.1 3.2M6.6 6.6C3.6 8.4 2 12 2 12s3.5 8 10 8a9 9 0 0 0 4.2-1"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>'
  };
  function icon(name, cls=''){ return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||''}</svg>`; }

  async function init(){
    if(!localStorage.getItem(K.clients)) write(K.clients,demo.clients);
    if(!localStorage.getItem(K.services)) write(K.services,demo.services);
    if(!localStorage.getItem(K.sales)) write(K.sales,demo.sales);
    if(!localStorage.getItem(K.cash)) write(K.cash,demo.cash);
    if(!localStorage.getItem(K.settings)) write(K.settings,{businessName:'Sigraf Gráfica',adminName:'Administrador'});
    state.logged = await checkSession();
    if(state.logged) await loadDatabase();
    loadState();
    if(databaseOnline){
      for(const key of ['clients','services','sales','cash','settings']){
        if(!databaseKeys.has(key)) saveDatabase(key,state[key] ?? read(K[key], null));
      }
    }
    render();
  }
  function loadState(){
    state.clients=read(K.clients,[]); state.services=read(K.services,[]); state.sales=read(K.sales,[]); state.cash=read(K.cash,[]); state.settings=read(K.settings,{businessName:'Sigraf Gráfica',adminName:'Administrador'});
  }
  function persist(key){ write(K[key],state[key]); saveDatabase(key,state[key]); }
  function persistByStorageKey(storageKey, value){ write(storageKey,value); const key=storageToState[storageKey]; if(key) saveDatabase(key,value); }
  function toast(msg,type='ok'){ const old=$('.toast'); if(old)old.remove(); const el=document.createElement('div');el.className='toast '+type;el.innerHTML=`${type==='ok'?icon('save','sm'):icon('warning','sm')}<span>${esc(msg)}</span>`;document.body.appendChild(el);setTimeout(()=>el.remove(),2600); }
  function confirmBox(msg){ return window.confirm(msg); }

  function render(){ state.logged ? renderShell() : renderLogin(); }

  function renderLogin(){
    app.innerHTML=`<div class="login-page">
      <section class="login-left">
        <div class="login-brand"><img src="${LOGO_SRC}" alt="Sigraf"><span>Gestão gráfica inteligente</span></div>
        <div class="login-box"><span class="eyebrow">PAINEL ADMINISTRATIVO</span><h1>Bem-vindo de volta.</h1><p>Entre para gerenciar serviços, caixa, vendas e clientes em um só lugar.</p>
          <form id="loginForm" class="login-form">
            <label class="field"><span>Usuário</span><input id="loginUser" autocomplete="username" required></label>
            <label class="field"><span>Senha</span><div class="password"><input id="loginPass" type="password" placeholder="Digite sua senha" autocomplete="current-password" required><button class="eye-btn" type="button" id="togglePass">${icon('eye','sm')}</button></div></label>
            <div class="error-box hidden" id="loginError">Usuário ou senha inválidos.</div>
            <button class="btn primary login-submit">Entrar no painel ${icon('chevron','sm')}</button>
          </form>
        </div>
      </section>
      <aside class="login-art"><div class="login-art-content"><span class="login-pill">SIGRAF GESTÃO</span><h2>Controle sua gráfica com <span>clareza e velocidade.</span></h2><p>Financeiro, produção, clientes e vendas conectados em uma experiência simples, moderna e profissional.</p><div class="art-stats"><div class="art-stat"><b>100%</b><small>RESPONSIVO</small></div><div class="art-stat"><b>24h</b><small>DISPONÍVEL</small></div><div class="art-stat"><b>1 painel</b><small>TODA OPERAÇÃO</small></div></div></div></aside>
    </div>`;
    $('#togglePass').onclick=()=>{ const p=$('#loginPass'); const show=p.type==='password';p.type=show?'text':'password';$('#togglePass').innerHTML=icon(show?'eyeoff':'eye','sm'); };
    $('#loginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#loginUser').value.trim(),password:$('#loginPass').value})});state.logged=true;await loadDatabase();loadState();render();}catch{$('#loginError').classList.remove('hidden');}};
  }

  function navItems(){ return [
    ['dashboard','Dashboard','dashboard'],['services','Serviços','printer'],['cash','Caixa','wallet'],['sales','Vendas','cart'],['clients','Clientes','users'],['reports','Relatórios','chart'],['settings','Configurações','settings']
  ]; }
  function renderShell(){
    app.innerHTML=`<div class="shell"><div id="overlay" class="overlay"></div><aside id="sidebar" class="sidebar ${state.sidebar?'open':''}"><div class="side-logo"><img src="${LOGO_SRC}" alt="Sigraf"></div><nav class="side-nav">${navItems().map(([id,label,ico])=>`<button class="side-link ${state.page===id?'active':''}" data-page="${id}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav><div class="side-footer"><div class="mini-brand"><div class="mini-ring"></div><div><b>${esc(state.settings.businessName)}</b><small>Gestão inteligente</small></div></div><button class="logout-btn" id="logoutBtn">${icon('logout')} Sair</button><small class="version">Versão 1.0.0</small></div></aside><main class="main"><header class="topbar"><div class="top-left"><button id="mobileMenu" class="mobile-menu">${icon('menu')}</button><div><h3>Olá, ${esc(state.settings.adminName)}!</h3><p>Bem-vindo ao painel da Sigraf.</p></div></div><div class="top-right"><div class="today">${icon('calendar','sm')} ${new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}</div><div class="avatar">${esc((state.settings.adminName||'A')[0].toUpperCase())}</div><button id="topLogout" class="top-logout">${icon('logout','sm')}</button></div></header><div id="content" class="content"></div></main></div>`;
    $$('.side-link').forEach(b=>b.onclick=()=>go(b.dataset.page));
    $('#logoutBtn').onclick=$('#topLogout').onclick=logout;
    $('#mobileMenu').onclick=()=>{state.sidebar=true;$('#sidebar').classList.add('open');$('#overlay').style.display='block';};
    $('#overlay').onclick=()=>{state.sidebar=false;$('#sidebar').classList.remove('open');$('#overlay').style.display='none';};
    renderPage();
  }
  function go(page){state.page=page;state.sidebar=false;renderShell();window.scrollTo(0,0);}
  function logout(){api('/api/logout',{method:'POST'}).catch(()=>{});state.logged=false;render();}

  function pageTitle(title,subtitle,ico,button=''){return `<div class="page-title"><div><span class="eyebrow">GESTÃO SIGRAF</span><h1>${ico?icon(ico,'lg'):''}${esc(title)}</h1><p>${esc(subtitle)}</p></div>${button}</div>`;}
  function panelHead(title,ico,action='',actionId=''){return `<div class="panel-head"><div class="panel-title">${icon(ico,'sm')}<h3>${esc(title)}</h3></div>${action?`<button class="panel-link" id="${actionId}">${esc(action)}${icon('chevron','sm')}</button>`:''}</div>`;}
  function formField(label,id,type='text',value='',opts=''){return `<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(value)}" ${opts}></label>`;}
  function selectField(label,id,value,options){return `<label class="field"><span>${esc(label)}</span><select id="${id}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;}
  function paymentField(id,value='PIX'){return selectField('Pagamento',id,value,['PIX','Dinheiro','Cartão','Transferência','Boleto']);}
  function emptyRow(text){return `<div class="empty">${icon('file','lg')}<b>${esc(text)}</b><span>Cadastre um novo item para começar.</span></div>`;}
  function badge(type){return `<span class="badge ${type==='entrada'?'entry':'exit'}">${type==='entrada'?'Entrada':'Saída'}</span>`;}
  function statusDot(status){const cls=status==='Aguardando'?'wait':status==='Em produção'?'production':status==='Pronto'?'ready':'done';return `<i class="dot ${cls}"></i>`;}
  function statusPill(status){return `<span class="status-pill">${statusDot(status)}${esc(status)}</span>`;}
  function actions(id,edit=true,remove=true){return `<div class="action-buttons">${edit?`<button class="icon-btn edit" data-id="${esc(id)}" title="Editar">${icon('edit','sm')}</button>`:''}${remove?`<button class="icon-btn trash remove" data-id="${esc(id)}" title="Excluir">${icon('trash','sm')}</button>`:''}</div>`;}
  function table(headers,rows){return `<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${rows.length?'':emptyRow('Nenhum registro encontrado.')}</div></section>`;}
  function listbar(placeholder,count,extra=''){return `<div class="listbar"><div class="searchbar">${icon('search','sm')}<input id="searchInput" placeholder="${esc(placeholder)}"></div>${extra||`<span class="count-pill">${count} registro${count===1?'':'s'}</span>`}</div>`;}
  function financeCard(label,value,ico,tone){return `<div class="finance-card"><span class="icon-ball tone-${tone}">${icon(ico)}</span><div><small>${esc(label)}</small><b>${esc(value)}</b></div></div>`;}

  function renderPage(){ const fn={dashboard:renderDashboard,services:renderServices,cash:renderCash,sales:renderSales,clients:renderClients,reports:renderReports,settings:renderSettings}[state.page]||renderDashboard; fn(); }

  function last7(type){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const iso=d.toISOString().slice(0,10);return state.cash.filter(x=>x.date===iso&&(!type||x.type===type)).reduce((a,b)=>a+Number(b.amount),0);});}
  function spark(values,color){const max=Math.max(...values,1),min=Math.min(...values,0),range=max-min||1;const pts=values.map((v,i)=>`${(i/(Math.max(values.length-1,1)))*100},${35-((v-min)/range)*29}`).join(' ');return `<div class="spark"><svg viewBox="0 0 100 40" preserveAspectRatio="none"><polyline points="${pts}" stroke="${color}"/></svg></div>`;}
  function kpi(label,value,sub,ico,tone,values){const colors={blue:'#078fe6',cyan:'#15a8e4',pink:'#ed008c',yellow:'#e9b500',dark:'#555e6b'};return `<div class="kpi"><span class="icon-ball tone-${tone}">${icon(ico)}</span><div class="kpi-meta"><span>${esc(label)}</span><b>${esc(value)}</b><small>${esc(sub)}</small></div>${spark(values,colors[tone])}</div>`;}
  function renderDashboard(){
    const entries=state.cash.filter(x=>x.type==='entrada').reduce((a,b)=>a+Number(b.amount),0);const exits=state.cash.filter(x=>x.type==='saida').reduce((a,b)=>a+Number(b.amount),0);const salesTotal=state.sales.reduce((a,b)=>a+Number(b.total),0);const ts=state.services.filter(x=>x.createdAt===todayISO()).length;const ready=state.services.filter(x=>x.status==='Pronto').length;const recent=[...state.cash].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);
    $('#content').innerHTML=pageTitle('Dashboard','Acompanhe os principais números da sua gráfica.','',`<button class="btn primary" id="newService">${icon('plus','sm')} Novo serviço</button>`)+`<div class="kpis">${kpi('Serviços do dia',ts,ready+' prontos para entrega','printer','blue',last7())}${kpi('Entradas',money(entries),'Total registrado','down','cyan',last7('entrada'))}${kpi('Saídas',money(exits),'Total registrado','up','pink',last7('saida'))}${kpi('Vendas de materiais',money(salesTotal),state.sales.length+' vendas registradas','cart','yellow',last7('entrada'))}${kpi('Clientes cadastrados',state.clients.length,'Base de clientes','users','dark',[2,4,3,6,7,8,10])}</div><div class="dash-grid"><section class="panel cash-panel">${panelHead('Movimentação de Caixa','wallet','Ver relatório completo','seeReports')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Categoria</th><th>Valor</th><th>Pagamento</th></tr></thead><tbody>${recent.map(r=>`<tr><td>${dateBR(r.date)}</td><td class="strong">${esc(r.description)}</td><td>${badge(r.type)}</td><td>${esc(r.category)}</td><td class="${r.type==='entrada'?'positive':'negative'}">${r.type==='entrada'?'+':'-'}${money(r.amount)}</td><td>${esc(r.paymentMethod)}</td></tr>`).join('')}</tbody></table>${recent.length?'':emptyRow('Nenhuma movimentação registrada.')}</div><div class="cash-summary"><div class="summary"><span class="icon-ball tone-blue">${icon('down','sm')}</span><div><small>Total de Entradas</small><b>${money(entries)}</b></div></div><div class="summary"><span class="icon-ball tone-pink">${icon('up','sm')}</span><div><small>Total de Saídas</small><b>${money(exits)}</b></div></div><div class="summary"><span class="icon-ball tone-dark">${icon('dollar','sm')}</span><div><small>Saldo</small><b>${money(entries-exits)}</b></div></div></div></section><section class="panel">${panelHead('Atalhos rápidos','package')}<div class="quick-grid">${quick('services','printer','Novo serviço','Registre uma ordem de produção.')}${quick('sales','cart','Nova venda','Venda materiais e lance no caixa.')}${quick('clients','users','Novo cliente','Cadastre dados e endereço.')}${quick('cash','wallet','Movimentar caixa','Lance entrada ou saída manual.')}</div></section><section class="promo"><div class="promo-copy"><span class="eyebrow">SIGRAF GESTÃO</span><h2>Qualidade que imprime <span>resultados.</span></h2><p>Organização financeira e produção conectadas para você vender mais e perder menos tempo.</p></div><div class="promo-rings"><i></i><i></i><i></i></div></section><section class="panel">${panelHead('Produção','clock','Ver serviços','seeServices')}<div class="status-list">${['Aguardando','Em produção','Pronto','Entregue'].map(s=>`<div class="status-line"><span class="status-name">${statusDot(s)}${s}</span><b>${state.services.filter(x=>x.status===s).length}</b></div>`).join('')}</div></section></div>`;
    $('#newService').onclick=()=>go('services');$('#seeReports').onclick=()=>go('reports');$('#seeServices').onclick=()=>go('services');$$('.quick').forEach(b=>b.onclick=()=>go(b.dataset.page));
  }
  function quick(page,ico,title,text){return `<button class="quick" data-page="${page}"><span class="quick-icon">${icon(ico,'sm')}</span><span class="quick-copy"><b>${esc(title)}</b><small>${esc(text)}</small></span>${icon('chevron','sm')}</button>`;}

  function clientOptions(value=''){return `<option value="">Cliente não informado</option>`+state.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('');}

  let editServiceId=null;
  function renderServices(search=''){
    const filtered=state.services.filter(s=>norm(s.description+' '+(state.clients.find(c=>c.id===s.clientId)?.name||'')).includes(norm(search)));
    const editing=editServiceId?state.services.find(s=>s.id===editServiceId):null;
    $('#content').innerHTML=pageTitle('Serviços','Controle ordens, produção, prazos e valores.','printer')+`<section class="panel form-panel"><h3>${editing?'Editar serviço':'Novo serviço'}</h3><form id="serviceForm" class="form-grid"><label class="field"><span>Cliente</span><select id="svcClient">${clientOptions(editing?.clientId||'')}</select></label><label class="field wide"><span>Descrição</span><input id="svcDesc" value="${esc(editing?.description||'')}" placeholder="Ex.: 1.000 panfletos 10x15 4x0" required></label>${formField('Quantidade','svcQty','number',editing?.qty||1,'min="1"')}${formField('Valor unitário','svcUnit','number',editing?.unitPrice||'','min="0" step="0.01" required')}${selectField('Status','svcStatus',editing?.status||'Aguardando',['Aguardando','Em produção','Pronto','Entregue'])}${formField('Prazo','svcDue','date',editing?.dueDate||todayISO())}${paymentField('svcPay',editing?.paymentMethod||'PIX')}<label class="field"><span>Total</span><div id="svcTotal" class="calc">${money((editing?.qty||1)*(editing?.unitPrice||0))}</div></label>${editing?'':`<label class="checkline"><input id="svcPaid" type="checkbox" checked> Registrar entrada no caixa automaticamente</label>`}<div class="form-actions">${editing?`<button type="button" class="btn" id="cancelService">${icon('close','sm')} Cancelar</button>`:''}<button class="btn primary">${icon('save','sm')} ${editing?'Salvar alterações':'Registrar serviço'}</button></div></form></section>${listbar('Buscar serviço ou cliente...',filtered.length)}${table(['Cliente','Serviço','Prazo','Status','Valor','Pagamento','Ações'],filtered.map(s=>{const c=state.clients.find(x=>x.id===s.clientId);return `<tr><td>${esc(c?.name||'—')}</td><td class="strong">${esc(s.description)}</td><td>${dateBR(s.dueDate)}</td><td>${statusPill(s.status)}</td><td>${money(s.total)}</td><td>${esc(s.paymentMethod)}</td><td>${actions(s.id)}</td></tr>`;}))}`;
    const updateTotal=()=>$('#svcTotal').textContent=money(Number($('#svcQty').value||0)*Number($('#svcUnit').value||0));$('#svcQty').oninput=updateTotal;$('#svcUnit').oninput=updateTotal;
    $('#serviceForm').onsubmit=e=>{e.preventDefault();const data={clientId:$('#svcClient').value,description:$('#svcDesc').value.trim(),qty:Number($('#svcQty').value||1),unitPrice:Number($('#svcUnit').value||0),status:$('#svcStatus').value,dueDate:$('#svcDue').value,paymentMethod:$('#svcPay').value};data.total=data.qty*data.unitPrice;if(editServiceId){state.services=state.services.map(x=>x.id===editServiceId?{...x,...data}:x);state.cash=state.cash.map(x=>x.source==='service'&&x.sourceId===editServiceId?{...x,description:data.description,amount:data.total,paymentMethod:data.paymentMethod}:x);}else{const id=uid();state.services.unshift({id,...data,createdAt:todayISO(),paid:$('#svcPaid').checked});if($('#svcPaid').checked)state.cash.unshift({id:uid(),date:todayISO(),type:'entrada',category:'Serviços',description:data.description,amount:data.total,paymentMethod:data.paymentMethod,source:'service',sourceId:id});}persist('services');persist('cash');editServiceId=null;toast('Serviço salvo com sucesso.');renderServices();};
    if($('#cancelService'))$('#cancelService').onclick=()=>{editServiceId=null;renderServices(search);};
    $('#searchInput').value=search;$('#searchInput').oninput=e=>renderServices(e.target.value);
    $$('.edit').forEach(b=>b.onclick=()=>{editServiceId=b.dataset.id;renderServices(search);window.scrollTo({top:0,behavior:'smooth'});});$$('.remove').forEach(b=>b.onclick=()=>{if(confirmBox('Excluir este serviço? A entrada vinculada também será removida.')){state.services=state.services.filter(x=>x.id!==b.dataset.id);state.cash=state.cash.filter(x=>!(x.source==='service'&&x.sourceId===b.dataset.id));persist('services');persist('cash');toast('Serviço excluído.');renderServices(search);}});
  }

  let editClientId=null;
  function renderClients(search=''){
    const filtered=state.clients.filter(c=>norm(Object.values(c).join(' ')).includes(norm(search)));const editing=editClientId?state.clients.find(c=>c.id===editClientId):null;
    $('#content').innerHTML=pageTitle('Clientes','Cadastre e encontre clientes rapidamente.','users')+`<section class="panel form-panel"><h3>${editing?'Editar cliente':'Cadastro de Cliente'}</h3><form id="clientForm" class="form-grid">${formField('Nome','clName','text',editing?.name||'','placeholder="Nome completo" required')}${formField('CPF / CNPJ','clCpf','text',editing?.cpf||'','placeholder="000.000.000-00"')}<label class="field wide"><span>Endereço</span><input id="clAddress" value="${esc(editing?.address||'')}" placeholder="Rua, número, bairro e cidade"></label>${formField('Referência','clRef','text',editing?.reference||'','placeholder="Ponto de referência"')}${formField('CEP','clCep','text',editing?.cep||'','placeholder="00000-000"')}<div class="form-actions">${editing?`<button type="button" class="btn" id="cancelClient">${icon('close','sm')} Cancelar</button>`:''}<button class="btn primary">${icon('users','sm')} ${editing?'Salvar alterações':'Cadastrar Cliente'}</button></div></form></section>${listbar('Buscar nome, CPF, CEP...',filtered.length)}${table(['Nome','CPF / CNPJ','Endereço','Referência','CEP','Ações'],filtered.map(c=>`<tr><td class="strong">${esc(c.name)}</td><td>${esc(c.cpf||'—')}</td><td>${esc(c.address||'—')}</td><td>${esc(c.reference||'—')}</td><td>${esc(c.cep||'—')}</td><td>${actions(c.id)}</td></tr>`))}`;
    $('#clientForm').onsubmit=e=>{e.preventDefault();const data={name:$('#clName').value.trim(),cpf:$('#clCpf').value.trim(),address:$('#clAddress').value.trim(),reference:$('#clRef').value.trim(),cep:$('#clCep').value.trim()};if(editClientId)state.clients=state.clients.map(x=>x.id===editClientId?{...x,...data}:x);else state.clients.unshift({id:uid(),...data,createdAt:todayISO()});persist('clients');editClientId=null;toast('Cliente salvo com sucesso.');renderClients();};
    if($('#cancelClient'))$('#cancelClient').onclick=()=>{editClientId=null;renderClients(search);};$('#searchInput').value=search;$('#searchInput').oninput=e=>renderClients(e.target.value);$$('.edit').forEach(b=>b.onclick=()=>{editClientId=b.dataset.id;renderClients(search);window.scrollTo({top:0,behavior:'smooth'});});$$('.remove').forEach(b=>b.onclick=()=>{const id=b.dataset.id;if(state.services.some(s=>s.clientId===id)||state.sales.some(s=>s.clientId===id)){toast('Cliente possui serviços ou vendas vinculados.','error');return;}if(confirmBox('Excluir este cliente?')){state.clients=state.clients.filter(x=>x.id!==id);persist('clients');toast('Cliente excluído.');renderClients(search);}});
  }

  function renderSales(search=''){
    const filtered=state.sales.filter(s=>norm(s.material+' '+(state.clients.find(c=>c.id===s.clientId)?.name||'')).includes(norm(search)));
    $('#content').innerHTML=pageTitle('Venda de Material','Registre vendas avulsas e lance no caixa automaticamente.','cart')+`<section class="panel form-panel"><h3>Nova venda</h3><form id="saleForm" class="form-grid"><label class="field"><span>Cliente</span><select id="saleClient">${clientOptions()}</select></label>${formField('Material','saleMaterial','text','','placeholder="Ex.: lona, adesivo, papel..." required')}${formField('Quantidade','saleQty','number',1,'min="1"')}${formField('Valor unitário','saleUnit','number','','min="0" step="0.01" required')}${paymentField('salePay')}<label class="field"><span>Total</span><div id="saleTotal" class="calc">${money(0)}</div></label><label class="checkline"><input id="salePaid" type="checkbox" checked> Registrar entrada no caixa automaticamente</label><div class="form-actions"><button class="btn primary">${icon('cart','sm')} Registrar venda</button></div></form></section>${listbar('Buscar material ou cliente...',filtered.length)}${table(['Data','Cliente','Material','Qtd.','Unitário','Total','Pagamento','Ações'],filtered.map(s=>`<tr><td>${dateBR(s.createdAt)}</td><td>${esc(state.clients.find(c=>c.id===s.clientId)?.name||'—')}</td><td class="strong">${esc(s.material)}</td><td>${s.qty}</td><td>${money(s.unitPrice)}</td><td>${money(s.total)}</td><td>${esc(s.paymentMethod)}</td><td>${actions(s.id,false,true)}</td></tr>`))}`;
    const upd=()=>$('#saleTotal').textContent=money(Number($('#saleQty').value||0)*Number($('#saleUnit').value||0));$('#saleQty').oninput=upd;$('#saleUnit').oninput=upd;
    $('#saleForm').onsubmit=e=>{e.preventDefault();const qty=Number($('#saleQty').value||1),unit=Number($('#saleUnit').value||0),id=uid(),data={id,clientId:$('#saleClient').value,material:$('#saleMaterial').value.trim(),qty,unitPrice:unit,total:qty*unit,paymentMethod:$('#salePay').value,createdAt:todayISO(),paid:$('#salePaid').checked};state.sales.unshift(data);if(data.paid)state.cash.unshift({id:uid(),date:todayISO(),type:'entrada',category:'Vendas',description:data.material,amount:data.total,paymentMethod:data.paymentMethod,source:'sale',sourceId:id});persist('sales');persist('cash');toast('Venda registrada.');renderSales();};
    $('#searchInput').value=search;$('#searchInput').oninput=e=>renderSales(e.target.value);$$('.remove').forEach(b=>b.onclick=()=>{if(confirmBox('Excluir esta venda? A entrada vinculada também será removida.')){state.sales=state.sales.filter(x=>x.id!==b.dataset.id);state.cash=state.cash.filter(x=>!(x.source==='sale'&&x.sourceId===b.dataset.id));persist('sales');persist('cash');toast('Venda excluída.');renderSales(search);}});
  }

  function renderCash(search='',filter='todos'){
    const entries=state.cash.filter(x=>x.type==='entrada').reduce((a,b)=>a+Number(b.amount),0),exits=state.cash.filter(x=>x.type==='saida').reduce((a,b)=>a+Number(b.amount),0);const filtered=state.cash.filter(x=>(filter==='todos'||x.type===filter)&&norm(x.description+' '+x.category).includes(norm(search))).sort((a,b)=>b.date.localeCompare(a.date));
    const segments=`<div class="segments">${[['todos','Todos'],['entrada','Entradas'],['saida','Saídas']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}</div>`;
    $('#content').innerHTML=pageTitle('Caixa','Acompanhe entradas, saídas e saldo financeiro.','wallet')+`<div class="finance-grid">${financeCard('Entradas',money(entries),'down','blue')}${financeCard('Saídas',money(exits),'up','pink')}${financeCard('Saldo',money(entries-exits),'dollar','dark')}</div><section class="panel form-panel"><h3>Novo lançamento</h3><form id="cashForm" class="form-grid">${formField('Data','cashDate','date',todayISO())}${selectField('Tipo','cashType','entrada',['entrada','saida'])}${formField('Categoria','cashCat','text','Outros','placeholder="Ex.: Serviços, aluguel, materiais"')}${formField('Descrição','cashDesc','text','','placeholder="Descrição do lançamento" required')}${formField('Valor','cashAmount','number','','min="0" step="0.01" required')}${paymentField('cashPay')}<div class="form-actions"><button class="btn primary">${icon('save','sm')} Registrar lançamento</button></div></form></section>${listbar('Buscar lançamento...',filtered.length,segments)}${table(['Data','Descrição','Tipo','Categoria','Valor','Pagamento','Origem','Ações'],filtered.map(x=>`<tr><td>${dateBR(x.date)}</td><td class="strong">${esc(x.description)}</td><td>${badge(x.type)}</td><td>${esc(x.category)}</td><td class="${x.type==='entrada'?'positive':'negative'}">${x.type==='entrada'?'+':'-'}${money(x.amount)}</td><td>${esc(x.paymentMethod)}</td><td>${x.source==='manual'?'Manual':x.source==='service'?'Serviço':'Venda'}</td><td>${actions(x.id,false,true)}</td></tr>`))}`;
    $('#cashForm').onsubmit=e=>{e.preventDefault();state.cash.unshift({id:uid(),date:$('#cashDate').value,type:$('#cashType').value,category:$('#cashCat').value.trim()||'Outros',description:$('#cashDesc').value.trim(),amount:Number($('#cashAmount').value||0),paymentMethod:$('#cashPay').value,source:'manual'});persist('cash');toast('Lançamento registrado.');renderCash(search,filter);};
    $('#searchInput').value=search;$('#searchInput').oninput=e=>renderCash(e.target.value,filter);$$('[data-filter]').forEach(b=>b.onclick=()=>renderCash(search,b.dataset.filter));$$('.remove').forEach(b=>b.onclick=()=>{const item=state.cash.find(x=>x.id===b.dataset.id);if(item?.source!=='manual'){toast('Exclua o serviço ou venda de origem.','error');return;}if(confirmBox('Excluir este lançamento?')){state.cash=state.cash.filter(x=>x.id!==b.dataset.id);persist('cash');toast('Lançamento excluído.');renderCash(search,filter);}});
  }

  function renderReports(from='',to=''){
    const range=d=>(!from||d>=from)&&(!to||d<=to);const c=state.cash.filter(x=>range(x.date)),s=state.services.filter(x=>range(x.createdAt)),v=state.sales.filter(x=>range(x.createdAt));const ent=c.filter(x=>x.type==='entrada').reduce((a,b)=>a+Number(b.amount),0),sai=c.filter(x=>x.type==='saida').reduce((a,b)=>a+Number(b.amount),0);
    $('#content').innerHTML=pageTitle('Relatórios','Filtre resultados e exporte os dados do caixa.','chart')+`<section class="panel report-filter"><div class="filter-left"><label class="filter-field"><span>Data inicial</span><input id="fromDate" type="date" value="${esc(from)}"></label><label class="filter-field"><span>Data final</span><input id="toDate" type="date" value="${esc(to)}"></label><button class="btn" id="clearReport">${icon('refresh','sm')} Limpar</button></div><button class="btn primary" id="exportCsv">${icon('download','sm')} Exportar CSV</button></section><div class="finance-grid report-kpis">${financeCard('Entradas no período',money(ent),'down','blue')}${financeCard('Saídas no período',money(sai),'up','pink')}${financeCard('Saldo do período',money(ent-sai),'dollar','dark')}${financeCard('Serviços no período',String(s.length),'printer','cyan')}</div><div class="report-grid"><section class="panel">${panelHead('Resumo comercial','cart')}<div class="report-lines"><div class="report-line"><span>Vendas de materiais</span><b>${v.length}</b></div><div class="report-line"><span>Faturamento em vendas</span><b>${money(v.reduce((a,b)=>a+Number(b.total),0))}</b></div><div class="report-line"><span>Serviços registrados</span><b>${s.length}</b></div><div class="report-line"><span>Clientes na base</span><b>${state.clients.length}</b></div></div></section><section class="panel">${panelHead('Formas de pagamento','wallet')}<div class="report-lines">${['PIX','Dinheiro','Cartão','Transferência','Boleto'].map(p=>`<div class="report-line"><span>${p}</span><b>${money(c.filter(x=>x.paymentMethod===p&&x.type==='entrada').reduce((a,b)=>a+Number(b.amount),0))}</b></div>`).join('')}</div></section></div>`;
    $('#fromDate').onchange=e=>renderReports(e.target.value,to);$('#toDate').onchange=e=>renderReports(from,e.target.value);$('#clearReport').onclick=()=>renderReports();$('#exportCsv').onclick=()=>{const lines=[['Data','Tipo','Categoria','Descrição','Valor','Pagamento'],...c.map(x=>[x.date,x.type,x.category,x.description,x.amount,x.paymentMethod])];const content=lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\n');download(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}),`sigraf-caixa-${todayISO()}.csv`);toast('Relatório CSV exportado.');};
  }

  function renderSettings(){
    $('#content').innerHTML=pageTitle('Configurações','Personalize acesso, identidade e backups do sistema.','settings')+`<div class="settings-grid"><section class="panel settings-card">${panelHead('Empresa','building')}<label>Nome da empresa<input id="setBusiness" value="${esc(state.settings.businessName)}"></label><label>Nome exibido no painel<input id="setAdmin" value="${esc(state.settings.adminName)}"></label><button class="btn primary" id="saveProfile">${icon('save','sm')} Salvar identidade</button></section><section class="panel settings-card">${panelHead('Segurança','users')}<p>Acesso gerenciado no servidor pela variável SIGRAF_USERS.</p><p class="warning">${icon('warning','sm')} Quando o servidor estiver rodando, os dados são sincronizados com o banco SQLite.</p></section><section class="panel settings-card">${panelHead('Backup','download')}<p>Exporte todos os clientes, serviços, vendas e caixa em um único arquivo JSON.</p><div class="settings-actions"><button class="btn primary" id="backupBtn">${icon('download','sm')} Exportar backup</button><label class="btn file-btn">${icon('upload','sm')} Restaurar backup<input id="restoreFile" type="file" accept="application/json"></label></div></section><section class="panel settings-card danger-panel">${panelHead('Restaurar demonstração','refresh')}<p>Substitui os dados atuais pelos registros de exemplo originais do sistema.</p><button class="btn danger" id="resetDemo">${icon('refresh','sm')} Restaurar dados</button></section></div>`;
    $('#saveProfile').onclick=()=>{state.settings={...state.settings,businessName:$('#setBusiness').value.trim()||'Sigraf Gráfica',adminName:$('#setAdmin').value.trim()||'Administrador'};persist('settings');toast('Identidade salva.');renderShell();};
    $('#backupBtn').onclick=()=>{const data={version:2,exportedAt:new Date().toISOString(),settings:state.settings,clients:state.clients,services:state.services,sales:state.sales,cash:state.cash};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`sigraf-backup-${todayISO()}.json`);toast('Backup exportado.');};
    $('#restoreFile').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.clients)||!Array.isArray(d.services)||!Array.isArray(d.sales)||!Array.isArray(d.cash))throw new Error();if(confirmBox('Restaurar este backup? Os dados atuais serão substituídos.')){state.clients=d.clients;state.services=d.services;state.sales=d.sales;state.cash=d.cash;if(d.settings)state.settings=d.settings;persist('clients');persist('services');persist('sales');persist('cash');persist('settings');toast('Backup restaurado.');renderShell();}}catch{toast('Arquivo de backup inválido.','error');}};r.readAsText(file);};
    $('#resetDemo').onclick=()=>{if(confirmBox('ATENÇÃO: apagar dados atuais e restaurar demonstração?')){state.clients=structuredClone(demo.clients);state.services=structuredClone(demo.services);state.sales=structuredClone(demo.sales);state.cash=structuredClone(demo.cash);persist('clients');persist('services');persist('sales');persist('cash');toast('Dados de demonstração restaurados.');renderSettings();}};
  }

  init();
})();
